#define RCC_APB1ENR  (*(volatile uint32_t *)0x40023840U)

/* GPIOA */
#define GPIOA_MODER  (*(volatile uint32_t *)0x40020000U)
#define GPIOA_AFRL   (*(volatile uint32_t *)0x40020020U)

/* USART2 */
#define USART2_SR    (*(volatile uint32_t *)0x40004400U)
#define USART2_DR    (*(volatile uint32_t *)0x40004404U)
#define USART2_BRR   (*(volatile uint32_t *)0x40004408U)
#define USART2_CR1   (*(volatile uint32_t *)0x4000440CU)
#define USART2_CR2   (*(volatile uint32_t *)0x40004410U)
#define USART2_CR3   (*(volatile uint32_t *)0x40004414U)

/* DMA1 Stream5 */
#define DMA1_HISR    (*(volatile uint32_t *)0x40026004U)
#define DMA1_HIFCR   (*(volatile uint32_t *)0x4002600CU)
#define DMA1_S5CR    (*(volatile uint32_t *)0x40026088U)
#define DMA1_S5NDTR  (*(volatile uint32_t *)0x4002608CU)
#define DMA1_S5PAR   (*(volatile uint32_t *)0x40026090U)
#define DMA1_S5M0AR  (*(volatile uint32_t *)0x40026094U)
#define DMA1_S5FCR   (*(volatile uint32_t *)0x4002609CU)

/* NVIC */
#define NVIC_ISER0   (*(volatile uint32_t *)0xE000E100U)
#define NVIC_ISER1	 (*(volatile uint32_t *)0xE000E104U)

#define NVIC_ICER0 	 (*(volatile uint32_t *)0xE000E180U)
#define NVIC_ICER1 	 (*(volatile uint32_t *)0xE000E184U)

#define NVIC_ICPR0 	 (*(volatile uint32_t *)0xE000E280U)
#define NVIC_ICPR1 	 (*(volatile uint32_t *)0xE000E284U)

/* DMA Flags */
#define DMA_FEIF5   (1U << 6U)
#define DMA_DMEIF5  (1U << 8U)
#define DMA_HTIF5    (1U << 10U)
#define DMA_TCIF5    (1U << 11U)
#define DMA_TEIF5	 (1U << 9U)

#define DMA_CLEAR_FLAGS (DMA_FEIF5 | DMA_DMEIF5 | DMA_TEIF5 | \
                         DMA_HTIF5 | DMA_TCIF5)

#define USART_ORE	 (1U << 3U)
#define USART_NE	 (1U << 2U)
#define USART_FE	 (1U << 1U)
#define USART_IDLE 	 (1U << 4U)

/* PACKET */
#define PACKET_MAX_LEN 32U

static char packet_buffer[PACKET_MAX_LEN + 1U];
static uint8_t packet_index = 0U;
static uint8_t packet_discard = 0U;

/* Configuration */
#define RX_SIZE      128U
#define USART2_DR_ADDRESS 0x40004404U

/* ==========================================
 * 2. Debug Variables
 * ========================================== */

volatile uint8_t rx_buffer[RX_SIZE];

volatile uint16_t read_pos = 0U;
volatile uint16_t write_pos = 0U;

volatile uint8_t last_byte = 0U;
volatile uint32_t processed_count = 0U;

volatile uint32_t dma_ht_count = 0U;
volatile uint32_t dma_tc_count = 0U;
volatile uint32_t dma_te_count = 0U;

volatile uint32_t usart_ore_count = 0U;
volatile uint32_t usart_error_flags = 0U;
volatile uint8_t  usart_rx_fault = 0U;
volatile uint32_t usart_idle_count = 0U;
volatile uint32_t idle_write_pos = 0U;
volatile uint8_t  rx_data_pending = 0U;

volatile uint32_t dma_total_received = 0U;

volatile uint8_t dma_rx_overflow = 0U;

volatile char last_packet[PACKET_MAX_LEN + 1U];
volatile uint32_t packet_complete_count = 0U;
volatile uint32_t packet_too_long_count = 0U;

volatile uint32_t dma_recovery_count = 0U;

/* ==========================================
 * 3. USART2 Configuration
 * ========================================== */

static void uart2_init(void)
{
    /* Enable GPIOA and USART2 clocks */
    RCC_AHB1ENR |= (1U << 0U);
    RCC_APB1ENR |= (1U << 17U);

    (void)RCC_AHB1ENR;
    (void)RCC_APB1ENR;

    /* PA3 Alternate Function Mode */
    GPIOA_MODER &= ~(3U << 6U);
    GPIOA_MODER |=  (2U << 6U);

    /* PA3 AF7: USART2_RX */
    GPIOA_AFRL &= ~(15U << 12U);
    GPIOA_AFRL |=  (7U << 12U);

    /* Disable USART during configuration */
    USART2_CR1 = 0U;
    USART2_CR2 = 0U;
    USART2_CR3 = 0U;

    /*
     * PCLK1 = 16 MHz
     * Baud Rate = 115200
     * Oversampling by 16
     * 8N1
     */
    USART2_BRR = 0x008BU;

    /* Clear old receive status */
    volatile uint32_t dummy;

    dummy = USART2_SR;
    dummy = USART2_DR;
    (void)dummy;
}

/* ==========================================
 * 4. DMA1 Stream5 Configuration
 * ========================================== */

static void uart_dma_rx_init(void)
{
    /* Enable DMA1 clock */
    RCC_AHB1ENR |= (1U << 21U);
    (void)RCC_AHB1ENR;

    /* Disable Stream5 */
    DMA1_S5CR &= ~(1U << 0U);

    while ((DMA1_S5CR & 1U) != 0U)
    {
    }

    /*
     * CHSEL = 4   (USART2_RX)
     * DIR   = 00  (Peripheral to Memory)
     * CIRC  = 1   (Circular Mode)
     * MINC  = 1   (Memory Increment)
     * PSIZE = 00  (8-bit)
     * MSIZE = 00  (8-bit)
     * HTIE  = 1
     * TCIE  = 1
     */
    DMA1_S5CR =
          (4U << 25U)
        | (1U << 10U)
        | (1U << 8U)
        | (1U << 4U)
        | (1U << 3U)
		| (1U << 2U);

    /* Direct Mode */
    DMA1_S5FCR = 0U;

    /* Peripheral Address */
    DMA1_S5PAR = USART2_DR_ADDRESS;

    /* Memory Address */
    DMA1_S5M0AR = (uint32_t)(uintptr_t)&rx_buffer[0];

    /* Transfer Size */
    DMA1_S5NDTR = RX_SIZE;

    /* Clear previous flags */
    DMA1_HIFCR = DMA_CLEAR_FLAGS;

}

/* ==========================================
 * 5. UART DMA Reception Start
 * ========================================== */

static void uart_dma_rx_start(void)
{
    /* Enable DMA1 Stream5 IRQ16 */
    NVIC_ISER0 = (1U << 16U);

    /* Enable USART2 IRQ38 */
    NVIC_ISER1 = (1U << 6U);

    /* Enable DMA1 Stream5 */
    DMA1_S5CR |= (1U << 0U);

    /* Enable USART DMA RX Request and Error IRQ */
    USART2_CR3 |= (1U << 6U)  // DMAR
                | (1U << 0U); // EIE

    /* Enable USART2 Receiver and IDLE IRQ */
    USART2_CR1 |= (1U << 13U) // UE
                | (1U << 2U)  // RE
                | (1U << 4U); // IDLEIE
}

/* ==========================================
 * 6. DMA Interrupt Handler
 * ========================================== */

void DMA1_Stream5_IRQHandler(void)
{
    uint32_t status = DMA1_HISR;

    if ((status & DMA_HTIF5) != 0U)
    {
        DMA1_HIFCR = DMA_HTIF5;
        dma_ht_count++;

        __atomic_store_n(&rx_data_pending, 1U, __ATOMIC_RELEASE);
    }

    if ((status & DMA_TCIF5) != 0U)
    {
        DMA1_HIFCR = DMA_TCIF5;
        dma_tc_count++;

        __atomic_store_n(&rx_data_pending, 1U, __ATOMIC_RELEASE);
    }

    if((status & DMA_TEIF5) != 0U){
    	DMA1_HIFCR = DMA_TEIF5;
    	dma_te_count++;

		usart_rx_fault = 1U;
    }
}

void USART2_IRQHandler(void)
{
	uint32_t status = USART2_SR;

	uint32_t errors = status & (USART_ORE | USART_NE | USART_FE);

	if(((status & USART_IDLE) != 0U) || (errors != 0U)){
		uint32_t dummy = USART2_DR;
		(void)dummy;
	}

	if((status & USART_IDLE) != 0U){
		usart_idle_count++;

		uint32_t remaining = (DMA1_S5NDTR & 0xFFFFU);

		idle_write_pos = (RX_SIZE - remaining) % RX_SIZE;

		__atomic_store_n(&rx_data_pending, 1U, __ATOMIC_RELEASE);

	}

	if(errors != 0U){

		usart_error_flags |= errors;

		if((errors & USART_ORE) != 0){
			usart_ore_count++;
		}

		usart_rx_fault = 1U;
	}
}

/*
 * Reconstruct the RX total from transfer-complete interrupts and NDTR.
 * This is a best-effort count, not an absolute DMA hardware counter:
 * coalesced/missed TC events or wrap races may undercount bytes.
 */
static uint8_t dma_get_total_received(uint32_t* total){

	for(uint8_t retry = 0U ; retry < 4U ; retry++){

		uint32_t tc_before = dma_tc_count;

		uint32_t remaining = DMA1_S5NDTR & 0xFFFFU;

		uint32_t flags = DMA1_HISR;

		uint32_t tc_after = dma_tc_count;

		if(tc_before != tc_after){
			continue;
		}

		if((flags & DMA_TCIF5) != 0U){
			continue;
		}

		*total = (RX_SIZE - remaining) + tc_after * RX_SIZE;

		return 1U;
	}

	return 0U;

}

static void packet_parser_push(uint8_t byte){

	if(byte == '\r'){
		byte = '\n';
	}

	if(byte == '\n' ){
		if((packet_index > 0U) && (packet_discard == 0U)){
			for(uint8_t i = 0U ; i < packet_index ; i++){
				last_packet[i] = packet_buffer[i];
			}
			last_packet[packet_index] = '\0';

			packet_complete_count++;
		}

		packet_index = 0U;
		packet_discard = 0U;

		return;
	}

	if(packet_discard != 0U){
		return;
	}

	if(packet_index < PACKET_MAX_LEN){
		packet_buffer[packet_index] = (char)byte;
		packet_index++;
	}
	else{
		packet_too_long_count++;
		packet_discard = 1U;

	}
}

/*
 * Software fault recovery:
 * - Mask relevant IRQs and stop new USART DMA requests.
 * - Disable DMA Stream5 and wait until EN reads as zero.
 * - Reinitialize USART/DMA, reset RX session and incomplete packet state.
 * - Clear NVIC pending bits and restart reception.
 * Old in-flight data is discarded; hardware error injection was not tested.
 * The EN wait has no timeout in this learning project.
 */
static void uart_dma_rx_recover(void)
{

    NVIC_ICER0 = (1U << 16U);
    NVIC_ICER1 = (1U << 6U);

    USART2_CR3 &= ~(1U << 6U);

    DMA1_S5CR &= ~(1U << 0U);

    while ((DMA1_S5CR & (1U << 0U)) != 0U)
    {

    }

    uart2_init();
    uart_dma_rx_init();

    /* Reset DMA reception progress */
    read_pos = 0U;
    write_pos = 0U;

    processed_count = 0U;
    dma_total_received = 0U;

    dma_ht_count = 0U;
    dma_tc_count = 0U;

    /* Discard any incomplete packet */
    packet_index = 0U;
    packet_discard = 0U;

    idle_write_pos = 0U;

    __atomic_store_n(
        &rx_data_pending,
        0U,
        __ATOMIC_RELEASE
    );

    /* Clear old pending interrupts */
    NVIC_ICPR0 = (1U << 16U);
    NVIC_ICPR1 = (1U << 6U);

    /* Clear Fault and restart reception */
    usart_rx_fault = 0U;

    uart_dma_rx_start();

    dma_recovery_count++;
}

/* ==========================================
 * 7. Main
 * ========================================== */

int main(void)
{
    /* Configure USART2 */
    uart2_init();

    /* Configure DMA */
    uart_dma_rx_init();

    uart_dma_rx_start();

    for (;;)
    {

        if (usart_rx_fault != 0U)
		{
        	uart_dma_rx_recover();
			continue;
		}

        uint8_t event = __atomic_exchange_n(&rx_data_pending, 0U, __ATOMIC_ACQ_REL);

        if(event == 0U){
        	continue;
        }

        uint32_t total_snapshot = 0U;

        if(dma_get_total_received(&total_snapshot) == 0U){
        	__atomic_store_n(&rx_data_pending, 1U, __ATOMIC_RELEASE);
        	continue;
        }

        if(total_snapshot < processed_count){
        	__atomic_store_n(&rx_data_pending, 1U, __ATOMIC_RELEASE);
        	continue;
        }

        dma_total_received = total_snapshot;

        /* Calculate DMA write position */
        write_pos =
            (uint16_t)(total_snapshot % RX_SIZE);

        uint32_t pending = total_snapshot - processed_count;

        if(pending > RX_SIZE){
        	dma_rx_overflow = 1U;
        	usart_rx_fault = 1U;
        	continue;
        }

        /* Process received bytes */
        while ((processed_count < total_snapshot) && (usart_rx_fault == 0U))
        {
        	uint32_t latest_total = 0U;

        	if(dma_get_total_received(&latest_total) == 0U){
        		__atomic_store_n(&rx_data_pending, 1U, __ATOMIC_RELEASE);
        		break;
        	}

        	if(latest_total < processed_count){
        		__atomic_store_n(&rx_data_pending, 1U, __ATOMIC_RELEASE);
        		break;
        	}

        	if ((latest_total - processed_count) > RX_SIZE)
			{
				dma_rx_overflow = 1U;
				usart_rx_fault = 1U;
				break;
			}

        	uint8_t byte = rx_buffer[read_pos];

            last_byte = byte;

            packet_parser_push(byte);

            read_pos =
                (uint16_t)((read_pos + 1U) % RX_SIZE);

            processed_count++;
        }
    }
}
